import json, tempfile, os
from pathlib import Path
from data_importer import normalize_csv, normalize_jsonl

schema = {"columns": [{"name": "code", "type": "string",
                       "unicode_normalization": "NFKC", "casefold": True,
                       "default": "Straße", "allowed_values": ["strasse"]}]}
with tempfile.TemporaryDirectory() as d:
    csv_path = Path(d) / "data.csv"
    csv_path.write_text('code\n ＳＴＲＡＳＳＥ \nStraße\nSTRASSE\n""\nx\n', encoding="utf-8")
    jsonl_path = Path(d) / "data.jsonl"
    jsonl_path.write_text("".join(json.dumps({"code": v}, ensure_ascii=False) + "\n"
        for v in [" ＳＴＲＡＳＳＥ ", "Straße", "STRASSE", None, "x"]), encoding="utf-8")
    for norm, path in ((normalize_csv, csv_path), (normalize_jsonl, jsonl_path)):
        r = norm(path, schema, duplicate_by=["code"])
        print(r["records"], r["accepted"], r["rejected"], r["duplicates"], r["errors"])
        r2 = norm(path, schema, deduplicate_by=["code"])
        print("dedup:", r2["accepted"], r2["deduplicated"], r2["records"])

# config errors
for bad in ({"casefold": "yes"}, {"casefold": 1}, {"casefold": None}):
    col = {"name": "code", "type": "string", **bad}
    try:
        normalize_csv("/nonexistent.csv", {"columns": [col]})
        print("NO ERROR", bad)
    except ValueError as e:
        print("ok:", e)
col = {"name": "n", "type": "integer", "casefold": True}
try:
    normalize_jsonl("/nonexistent.jsonl", {"columns": [col]})
except ValueError as e:
    print("ok:", e)
# structure check still first
try:
    normalize_csv("/nonexistent.csv", {"columns": [{"name": "f", "type": "nope", "casefold": "x"}]})
except ValueError as e:
    print("ok:", e)
